CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE network_version (
    network_version TEXT NOT NULL,
    timetable_version TEXT,
    policy_version TEXT,
    rule_catalogue_version TEXT,
    raw JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    description TEXT NOT NULL,
    source_hashes JSONB NOT NULL,
    validator_report JSONB,
    dq_report JSONB,
    PRIMARY KEY (network_version)
);

CREATE TABLE operational_point (
    network_version TEXT NOT NULL,
    timetable_version TEXT,
    policy_version TEXT,
    rule_catalogue_version TEXT,
    raw JSONB NOT NULL,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    seq BIGINT NOT NULL,
    km DOUBLE PRECISION NOT NULL,
    km_ref_hwh DOUBLE PRECISION,
    lat DOUBLE PRECISION,
    lon DOUBLE PRECISION,
    type TEXT NOT NULL CHECK (type IN ('block_station_A', 'block_station_B', 'block_station_C', 'halt', 'ibh', 'cabin')),
    is_junction BOOLEAN NOT NULL,
    is_halt BOOLEAN NOT NULL,
    is_cabin BOOLEAN NOT NULL,
    is_boundary BOOLEAN NOT NULL,
    signalling TEXT,
    interlocking_std TEXT,
    block_instrument TEXT,
    crossing_facility BOOLEAN NOT NULL,
    traction_change BOOLEAN NOT NULL,
    crew_change BOOLEAN NOT NULL,
    kavach BOOLEAN NOT NULL,
    valid_from DATE,
    valid_to DATE,
    geom geometry(Point, 4326) GENERATED ALWAYS AS (CASE WHEN lon IS NOT NULL AND lat IS NOT NULL THEN ST_SetSRID(ST_MakePoint(lon, lat), 4326) END) STORED,
    PRIMARY KEY (network_version, code)
);

CREATE TABLE block_section (
    network_version TEXT NOT NULL,
